"""Generated by StepForge — by Md Zarin Tasnim. Phone and desktop-app steps through Appium, done the way StepForge
does them: every lookup and check waits (30 s by default), and an element is found by the first of its locators that
matches. `locators` is a list of Appium selectors (strategy, value), best first.
"""
import os
import re
import time

from selenium.common.exceptions import WebDriverException
from selenium.webdriver.remote.command import Command

# Android key codes for the key names StepForge uses.
ANDROID_KEYS = {
    "Enter": 66, "Tab": 61, "Escape": 111, "Backspace": 67, "Delete": 112, "Space": 62, "ArrowUp": 19,
    "ArrowDown": 20, "ArrowLeft": 21, "ArrowRight": 22, "Home": 3, "Menu": 82, "Search": 84,
}
# iOS has no key codes: these keys are typed into the focused field.
IOS_KEYS = {"Enter": "\n", "Tab": "\t", "Backspace": "\b", "Space": " "}
# W3C key values for desktop shortcuts ("Control+S", "Meta+Shift+N").
W3C_KEYS = {
    "Enter": "", "Return": "", "Tab": "", "Escape": "", "Backspace": "",
    "Delete": "", "Space": " ", "ArrowLeft": "", "ArrowUp": "", "ArrowRight": "",
    "ArrowDown": "", "Home": "", "End": "", "PageUp": "", "PageDown": "",
    "Shift": "", "Control": "", "Ctrl": "", "Alt": "", "Option": "",
    "Meta": "", "Command": "", "Cmd": "",
    **{f"F{i + 1}": chr(0xE031 + i) for i in range(12)},
}
PERMISSIONS = {
    "camera": (["android.permission.CAMERA"], "camera"),
    "location": (["android.permission.ACCESS_FINE_LOCATION", "android.permission.ACCESS_COARSE_LOCATION"], "location"),
    "microphone": (["android.permission.RECORD_AUDIO"], "microphone"),
    "contacts": (["android.permission.READ_CONTACTS"], "contacts"),
    "photos": (["android.permission.READ_MEDIA_IMAGES"], "photos"),
    "notifications": (["android.permission.POST_NOTIFICATIONS"], ""),
    "calendar": (["android.permission.READ_CALENDAR"], "calendar"),
}


def _literal(s):
    """An XPath string literal for any text."""
    if "'" not in s:
        return f"'{s}'"
    if '"' not in s:
        return f'"{s}"'
    return "concat(" + ", \"'\", ".join(f"'{p}'" for p in s.split("'")) + ")"


def _predicate(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


class App:
    """The app under test. `platform`: android, ios, macos, windows or linux."""

    def __init__(self, driver, platform, timeout=30):
        self.driver = driver
        self.platform = platform
        self.timeout = timeout
        self._app_id = None

    # ─── Finding ────────────────────────────────────────────────────────────
    def _all(self, locators):
        """The elements the first matching selector finds now (no waiting), or []."""
        for using, value in locators:
            try:
                found = self.driver.execute(Command.FIND_ELEMENTS, {"using": using, "value": value})["value"]
            except WebDriverException as e:
                if "invalid selector" in str(e).lower():
                    raise AssertionError(f"Invalid locator {using}={value}: {e.msg}") from e
                found = []
            if found:
                return found
        return []

    def find(self, locators, timeout=None):
        deadline = time.time() + (self.timeout if timeout is None else timeout)
        while True:
            found = self._all(locators)
            if found:
                return found[0]
            if time.time() >= deadline:
                raise AssertionError(f"No element found within {self.timeout if timeout is None else timeout} s: {locators}")
            time.sleep(0.25)

    def _try(self, f):
        try:
            return f()
        except WebDriverException:
            return None

    # ─── Actions ────────────────────────────────────────────────────────────
    def click(self, locators):
        self.find(locators).click()

    def double_click(self, locators):
        el = self.find(locators)
        if self.platform == "android":
            self.driver.execute_script("mobile: doubleClickGesture", {"elementId": el.id})
        elif self.platform == "ios":
            self.driver.execute_script("mobile: doubleTap", {"elementId": el.id})
        elif self.platform == "macos":
            self.driver.execute_script("macos: doubleClick", {"elementId": el.id})
        else:
            el.click()
            el.click()

    def fill(self, locators, text):
        el = self.find(locators)
        el.clear()
        el.send_keys(str(text))

    def type(self, locators, text):
        self.find(locators).send_keys(str(text))

    def clear(self, locators):
        self.find(locators).clear()

    def is_checked(self, el):
        if self.platform == "android":
            return el.get_attribute("checked") == "true"
        if self.platform in ("ios", "macos"):
            return el.get_attribute("value") in ("1", "true")
        if self.platform == "windows":
            state = self._try(lambda: el.get_attribute("Toggle.ToggleState")) or ""
            return re.match(r"^(on|1|true)$", state, re.I) is not None
        return el.get_attribute("checked") == "true"

    def set_checked(self, locators, want):
        el = self.find(locators)
        if self.is_checked(el) != want:
            el.click()

    def select(self, locators, label):
        """A spinner or pop-up: opens it, then taps the option with that text."""
        self.click(locators)
        self.click(self._text(str(label)))

    def _text(self, text):
        p = self.platform
        if p == "android":
            return [("-android uiautomator", f"new UiSelector().text({_predicate(text)})")]
        if p == "ios":
            return [("-ios predicate string", f"label == {_predicate(text)} OR value == {_predicate(text)}")]
        if p == "macos":
            return [("-ios predicate string", f"title == {_predicate(text)} OR label == {_predicate(text)} OR value == {_predicate(text)}")]
        return [("name", text)]

    def press(self, key, locators=None):
        el = self.find(locators) if locators else None
        if el is not None:
            el.click()
        if self.platform == "android":
            if key == "Back":
                return self.driver.back()
            if key not in ANDROID_KEYS:
                raise AssertionError(f'The key "{key}" is not available on Android')
            return self.driver.execute_script("mobile: pressKey", {"keycode": ANDROID_KEYS[key]})
        if self.platform == "ios":
            if key == "Home":
                return self.driver.execute_script("mobile: pressButton", {"name": "home"})
            if key not in IOS_KEYS:
                raise AssertionError(f'The key "{key}" is not available on iOS')
            target = el if el is not None else self.driver.switch_to.active_element
            return target.send_keys(IOS_KEYS[key])
        self.shortcut(key)

    def shortcut(self, combo):
        """A key or a shortcut ("Control+S") with W3C key actions: modifiers down, the key, modifiers up."""
        keys = []
        for k in [x.strip() for x in combo.split("+") if x.strip()]:
            v = W3C_KEYS.get(k) or W3C_KEYS.get(k[:1].upper() + k[1:]) or (k if len(k) == 1 else None)
            if v is None:
                raise AssertionError(f'Unknown key "{k}" in "{combo}"')
            keys.append(v)
        actions = [{"type": "keyDown", "value": v} for v in keys] + [{"type": "keyUp", "value": v} for v in reversed(keys)]
        self.driver.execute(Command.W3C_ACTIONS, {"actions": [{"type": "key", "id": "keyboard", "actions": actions}]})

    # ─── Checks and reading ─────────────────────────────────────────────────
    def read(self, source, locators, attribute=None):
        if source == "count":
            return len(self._all(locators))
        el = self.find(locators)
        if source == "attribute":
            return el.get_attribute(attribute)
        return (el.text or "").strip()

    def expect(self, check, locators, expected=None, attribute=None):
        """Waits until the check passes (as StepForge's assert step), else fails with what was seen."""
        deadline = time.time() + self.timeout
        seen = "not found"
        while True:
            ok, seen = self._check(check, locators, expected, attribute)
            if ok:
                return
            if time.time() >= deadline:
                raise AssertionError(f"Expected {check}{'' if expected is None else f' {expected!r}'}, but got {seen}")
            time.sleep(0.25)

    def _check(self, check, locators, expected, attribute):
        try:
            found = self._all(locators)
            if check == "count":
                return len(found) == int(expected), f"{len(found)} found"
            if check == "hidden":
                visible = bool(found) and found[0].is_displayed()
                return not visible, "visible" if visible else "not visible"
            if not found:
                return False, "not found"
            el = found[0]
            if check == "visible":
                return el.is_displayed(), "present but not visible"
            if check in ("enabled", "disabled"):
                enabled = el.is_enabled()
                return enabled == (check == "enabled"), "enabled" if enabled else "disabled"
            if check in ("checked", "unchecked"):
                checked = self.is_checked(el)
                return checked == (check == "checked"), "checked" if checked else "unchecked"
            if check == "attribute":
                value = el.get_attribute(attribute)
                return value == str(expected), repr(value)
            text = (el.text or "").strip()
            if check in ("text", "value"):
                return text == str(expected), repr(text)
            if check == "textContains":
                return str(expected) in text, repr(text)
            if check == "textMatches":
                return re.search(str(expected), text) is not None, repr(text)
            raise AssertionError(f'Unknown check "{check}"')
        except WebDriverException as e:
            return False, f"not ready ({e.msg})"

    def wait_for(self, locators, state="visible"):
        self.expect("hidden" if state in ("hidden", "detached") else "visible", locators)

    def screenshot(self, name, locators=None):
        os.makedirs("screenshots", exist_ok=True)
        path = os.path.join("screenshots", f"{name}.png")
        if locators:
            self.find(locators).screenshot(path)
        else:
            self.driver.get_screenshot_as_file(path)
        return path

    # ─── Gestures ───────────────────────────────────────────────────────────
    def _area(self):
        size = self.driver.get_window_size()
        w, h = size["width"], size["height"]
        return {"left": round(w * 0.1), "top": round(h * 0.2), "width": round(w * 0.8), "height": round(h * 0.6)}

    def scroll(self, direction="down"):
        """Scrolls the screen; False when it could not move any more (Android says so)."""
        p = self.platform
        if p == "android":
            return self.driver.execute_script("mobile: scrollGesture", {**self._area(), "direction": direction, "percent": 0.75}) is True
        if p == "ios":
            # A swipe up moves the content down.
            self.driver.execute_script("mobile: swipe", {"direction": "up" if direction == "down" else "down"})
        elif p == "macos":
            self.driver.execute_script("macos: scroll", {"x": 400, "y": 300, "deltaX": 0, "deltaY": -200 if direction == "down" else 200})
        elif p == "windows":
            self.driver.execute_script("windows: scroll", {"deltaY": -360 if direction == "down" else 360})
        else:
            self.shortcut("PageDown" if direction == "down" else "PageUp")
        return True

    def scroll_to(self, locators, direction="down", max_swipes=10):
        """Looks, scrolls, looks again, until the element shows or the screen stops moving."""
        stuck = 0
        for i in range(max_swipes + 1):
            found = self._all(locators)
            if found and self._try(found[0].is_displayed):
                return found[0]
            if i == max_swipes or stuck >= 2:
                break
            before = self._try(lambda: self.driver.page_source) or ""
            self.scroll(direction)
            time.sleep(0.4)
            after = self._try(lambda: self.driver.page_source) or ""
            stuck = stuck + 1 if before and before == after else 0
        raise AssertionError(f"Scrolled {direction} and the element did not show: {locators}")

    def swipe(self, direction, percent=0.75):
        self._swipe(direction, percent, None)

    def swipe_on(self, locators, direction, percent=0.75):
        self._swipe(direction, percent, self.find(locators))

    def _swipe(self, direction, percent, el):
        p = self.platform
        if p == "android":
            area = {"elementId": el.id} if el is not None else self._area()
            self.driver.execute_script("mobile: swipeGesture", {**area, "direction": direction, "percent": percent})
        elif p in ("ios", "macos"):
            self.driver.execute_script(f"{'mobile' if p == 'ios' else 'macos'}: swipe", {"direction": direction, **({"elementId": el.id} if el is not None else {})})
        else:
            raise AssertionError("A swipe is for phone apps; desktop apps use the mouse, keyboard and menus")

    def drag(self, locators, to):
        a, b = self.find(locators), self.find(to)
        ra, rb = a.rect, b.rect
        cx, cy = round(rb["x"] + rb["width"] / 2), round(rb["y"] + rb["height"] / 2)
        p = self.platform
        if p == "android":
            self.driver.execute_script("mobile: dragGesture", {"elementId": a.id, "endX": cx, "endY": cy})
        elif p == "ios":
            self.driver.execute_script("mobile: dragFromToForDuration", {"duration": 1, "fromX": round(ra["x"] + ra["width"] / 2), "fromY": round(ra["y"] + ra["height"] / 2), "toX": cx, "toY": cy})
        elif p == "macos":
            self.driver.execute_script("macos: clickAndDrag", {"startX": round(ra["x"] + ra["width"] / 2), "startY": round(ra["y"] + ra["height"] / 2), "endX": cx, "endY": cy, "duration": 1})
        elif p == "windows":
            self.driver.execute_script("windows: clickAndDrag", {"startElementId": a.id, "endElementId": b.id})
        else:
            raise AssertionError("Drag and drop is not available in Linux apps")

    def long_press(self, locators, ms=1000):
        el = self.find(locators)
        p = self.platform
        if p == "android":
            self.driver.execute_script("mobile: longClickGesture", {"elementId": el.id, "duration": ms})
        elif p == "ios":
            self.driver.execute_script("mobile: touchAndHold", {"elementId": el.id, "duration": ms / 1000})
        elif p == "macos":
            self.driver.execute_script("macos: press", {"elementId": el.id, "duration": ms / 1000})
        else:
            raise AssertionError("A long press is for phone apps; desktop apps use the mouse, keyboard and menus")

    def back(self):
        self.driver.back()

    def hide_keyboard(self):
        if self.platform not in ("android", "ios"):
            return
        if self._try(lambda: self.driver.execute_script("mobile: isKeyboardShown")) is False:
            return
        if self.platform == "android":
            self.driver.execute_script("mobile: hideKeyboard")
        else:
            # iOS hides the keyboard through one of its keys.
            self.driver.execute_script("mobile: hideKeyboard", {"keys": ["done", "Done", "return", "Return"]})

    def rotate(self, orientation):
        self.driver.orientation = "PORTRAIT" if orientation == "portrait" else "LANDSCAPE"

    # ─── The app and the device ─────────────────────────────────────────────
    def app_id(self):
        if self._app_id:
            return self._app_id
        caps = self.driver.capabilities
        p = self.platform
        if p == "android":
            self._app_id = caps.get("appPackage") or caps.get("appium:appPackage") or self.driver.execute_script("mobile: getCurrentPackage")
        elif p == "ios":
            self._app_id = caps.get("bundleId") or caps.get("appium:bundleId") or (self.driver.execute_script("mobile: activeAppInfo") or {}).get("bundleId")
        else:
            self._app_id = caps.get("bundleId") or caps.get("appium:bundleId") or caps.get("appPath") or caps.get("appium:appPath")
        return self._app_id

    def _app(self):
        key = "appId" if self.platform == "android" else "bundleId"
        if self.platform == "macos" and not (self.driver.capabilities.get("bundleId") or self.driver.capabilities.get("appium:bundleId")):
            return {"path": self.app_id()}
        return {key: self.app_id()}

    def launch_app(self):
        self._app_action("activateApp")

    def close_app(self):
        self._app_action("terminateApp")

    def reset_app(self):
        if self.platform not in ("android", "ios"):
            raise AssertionError('"reset" is for phone apps; close and launch the app instead')
        self.driver.execute_script("mobile: clearApp", self._app())

    def _app_action(self, name):
        p = self.platform
        if p in ("android", "ios"):
            self.driver.execute_script(f"mobile: {name}", self._app())
        elif p == "macos":
            self.driver.execute_script(f"macos: {name}", self._app())
        elif p == "windows":
            self.driver.execute_script("windows: launchApp" if name == "activateApp" else "windows: closeApp")
        else:
            raise AssertionError("Each Linux test starts and closes the app itself")

    def background_app(self, seconds=-1):
        if self.platform not in ("android", "ios"):
            raise AssertionError('"background" is for phone apps; close and launch the app instead')
        self.driver.execute_script("mobile: backgroundApp", {"seconds": seconds})

    def deep_link(self, url):
        p = self.platform
        if p == "android":
            self.driver.execute_script("mobile: deepLink", {"url": url, "package": self.app_id()})
        elif p == "ios":
            self.driver.execute_script("mobile: deepLink", {"url": url, "bundleId": self.app_id()})
        elif p == "macos":
            self.driver.execute_script("macos: deepLink", {"url": url, **self._app()})
        else:
            raise AssertionError("Opening a deep link is for phone apps")

    def set_location(self, latitude, longitude):
        if self.platform == "android":
            self.driver.execute_script("mobile: setGeolocation", {"latitude": latitude, "longitude": longitude})
        elif self.platform == "ios":
            self.driver.execute_script("mobile: setSimulatedLocation", {"latitude": latitude, "longitude": longitude})
        else:
            raise AssertionError("Setting the location is for phone apps")

    def permission(self, name, grant=True):
        android, ios = PERMISSIONS.get(name.lower(), ([name], name))
        if self.platform == "android":
            self.driver.execute_script("mobile: changePermissions", {"permissions": android, "appPackage": self.app_id(), "action": "grant" if grant else "revoke"})
        elif self.platform == "ios":
            if not ios:
                raise AssertionError(f"On iOS the app itself asks for the {name} permission: answer its dialog")
            self.driver.execute_script("mobile: setPermission", {"bundleId": self.app_id(), "access": {ios: "yes" if grant else "no"}})
        else:
            raise AssertionError("Granting permissions is for phone apps")

    def push_notification(self, title, body):
        if self.platform != "ios":
            raise AssertionError("Sending a notification works on iOS simulators (Android needs the app's own push service)")
        self.driver.execute_script("mobile: pushNotification", {"bundleId": self.app_id(), "payload": {"aps": {"alert": {"title": title, "body": body}, "sound": "default"}}})

    def menu(self, path):
        """A desktop app's menu path: "File > Save"."""
        titles = [t.strip() for t in str(path).split(">") if t.strip()]
        for i, title in enumerate(titles):
            if self.platform == "macos":
                kind = "XCUIElementTypeMenuBarItem" if i == 0 else "XCUIElementTypeMenuItem"
                queries = [("-ios class chain", f"**/{kind}[`title == {_predicate(title)}`]")]
            elif self.platform == "windows":
                queries = [("xpath", f"//MenuItem[@Name={_literal(title)}]")]
            elif self.platform == "linux":
                queries = [("xpath", f"//{'menu' if i == 0 else 'menu_item'}[@name={_literal(title)}]"), ("xpath", f"//menu[@name={_literal(title)}]")]
            else:
                raise AssertionError("Menu bars are for desktop apps; in a phone app tap the menu button instead")
            self.find(queries, timeout=10).click()

    def handle_dialog(self, accept=True, button=None):
        """Answers the dialog on screen, waiting for it to appear."""
        deadline = time.time() + self.timeout
        while True:
            try:
                if self._dialog(accept, button):
                    return
            except WebDriverException as e:
                if not re.search(r"no such alert|no alert|not.*(present|open|shown)|cannot be found", str(e), re.I):
                    raise
            if time.time() >= deadline:
                raise AssertionError(f"No dialog appeared within {self.timeout} s")
            time.sleep(0.25)

    def _dialog(self, accept, button):
        p = self.platform
        if p == "android":
            self.driver.execute_script("mobile: acceptAlert" if accept else "mobile: dismissAlert", {"buttonLabel": button} if button else {})
            return True
        if p == "ios":
            self.driver.execute_script("mobile: alert", {"action": "accept" if accept else "dismiss", **({"buttonLabel": button} if button else {})})
            return True
        label = button or ("OK" if accept else "Cancel")
        if p == "macos":
            sheets = [("-ios class chain", "**/XCUIElementTypeSheet")]
            found = self._all([("-ios class chain", f"**/XCUIElementTypeButton[`title == {_predicate(label)}`]")])
            if not found and not button and self._all(sheets):
                found = self._all([("accessibility id", "action-button-1" if accept else "action-button-2")])
            if not found:
                return False
            self._try(found[0].click)
            # A sheet can report its buttons at the wrong place (several displays): the keyboard answers it.
            for _ in range(6):
                time.sleep(0.25)
                if not self._all(sheets):
                    return True
            self.shortcut("Escape" if (not accept and not button) or re.match(r"^cancel$", label, re.I) else "Enter")
            return True
        if p == "windows":
            queries = [("xpath", f"//Window//Button[@Name={_literal(label)}]")]
        else:
            queries = [("xpath", f"//alert//push_button[@name={_literal(label)}]"), ("xpath", f"//dialog//push_button[@name={_literal(label)}]")]
        if not self._all(queries):
            return False
        # A dialog that is still opening ignores the first press: press until it has gone.
        for _ in range(5):
            found = self._all(queries)
            if not found:
                return True
            self._try(found[0].click)
            for _ in range(8):
                time.sleep(0.25)
                if not self._all(queries):
                    return True
        raise AssertionError("The dialog did not close after pressing its button")
